from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import IoTDeviceTelemetry

class DeviceTelemetryHStoreSearchView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request):
        attr_key = request.query_params.get('attr_key')
        attr_val = request.query_params.get('attr_val')
        if not attr_key or not attr_val:
            return Response({"error": "Missing key or val"}, status=status.HTTP_400_BAD_REQUEST)

        # Restrict HStore query to the authenticated organization's telemetry
        records = IoTDeviceTelemetry.objects.filter(
            organization=request.user.organization,
            attributes__contains={attr_key: attr_val}
        ).values('id', 'device_serial', 'attributes', 'recorded_at')[:50]

        return Response({"matches": list(records)})
